  "preferred_configuration": {
    "prize_parts": [
      {
        "ballot_id": "B026",
        "laureates": [
          "Charles L. Kane",
          "Laurens W. Molenkamp",
          "Qi-Kun Xue"
        ],
        "citation": "For the prediction and experimental realization of topological insulating phases of matter."
      }
    ]
  },
  "alternatives": [
    "B020",
    "B005"
  ],
  "statement": {
    "case_for": "Topological insulating phases revealed new quantum behavior in solids and established a framework that has reshaped condensed-matter physics. The combination of theoretical prediction and experimental realization makes the physical claim especially compelling, and the phenomena have been studied across material systems for many years.",
    "case_against": "B026 groups the quantum spin Hall and quantum anomalous Hall effects, whose milestones and contributions do not map neatly onto one three-person attribution. The prize would need a carefully bounded citation and a clear account of each laureate's role.",
    "responses": [
      {
        "member_id": "danielsson-ulf",
        "point": "He argues that WMAP's precise CMB mapping established a quantitative standard model of cosmology, with conclusions checked and extended by later experiments, while noting the challenge of separating WMAP's contribution from the wider CMB program.",
        "response": "That is a strong case for a mature and consequential measurement. I would still give priority to B026 because its central claim is the prediction and realization of new phases of matter, rather than a major advance in precision within an already established measurement program. The attribution concern Danielsson identifies for WMAP also deserves attention in B026, though it is a different historical problem."
      },
      {
        "member_id": "olsson-eva",
        "point": "She describes X-ray free-electron lasers as a major source invention that opened ultrafast, atomic-scale X-ray science, while emphasizing the difficulty of distinguishing foundational contributions from the teams that built and operated facilities.",
        "response": "The scientific reach and maturity of the source class make B016 a serious candidate. Its facility-scale development and distributed contributions make the individual attribution particularly difficult to delimit. B026 also needs sharper boundaries, but its proposed recognition can be centered on a specific change in our understanding of quantum matter."
      }
    ],
    "uncertainties": [
      "The shortlist's grouping of quantum spin Hall and quantum anomalous Hall effects needs a precise historical account to establish which milestones and contributions the citation recognizes."
    ],
    "conflict_note": "None apparent from the supplied profile."
  }
}
